  "Managing roles": "Rollen verwalten",
  "Built-in roles cannot be changed. Copy one to start a custom role, then set exactly what it may do. Give a role for one system or object only, from a person's grants.": "Integrierte Rollen können nicht geändert werden. Kopieren Sie eine, um eine eigene Rolle zu beginnen, und legen Sie genau fest, was sie darf. Vergeben Sie eine Rolle nur für ein System oder Objekt über die Zuweisungen einer Person.",
