  "What each role may do": "Was jede Rolle darf",
  "The actions each role allows, by resource. Open a role to see or change its full matrix.": "Die Aktionen, die jede Rolle erlaubt, nach Ressource. Öffnen Sie eine Rolle, um ihre vollständige Matrix zu sehen oder zu ändern.",
