  "How the button reads on the sign-in page, who may use it, and whether passwords still work.": "Wie die Schaltfläche auf der Anmeldeseite heißt, wer sie verwenden darf und ob Passwörter noch funktionieren.",
  "Single sign-on is not set up yet, so there is nothing to show on the sign-in page. Set it up under ": "Single Sign-on ist noch nicht eingerichtet, daher gibt es auf der Anmeldeseite nichts anzuzeigen. Richten Sie es ein unter ",
  "Single sign-on": "Single Sign-on",
  "Shown as “Sign in with …”.": "Angezeigt als „Anmelden mit …“.",
  "Allowed email domains": "Erlaubte E-Mail-Domänen",
  "Only these domains can sign in and link to an existing account by email. Empty means nobody can.": "Nur diese Domänen können sich anmelden und per E-Mail mit einem bestehenden Konto verknüpfen. Leer bedeutet niemand.",
  "example.com, example.org": "example.com, example.org",
  "Require single sign-on": "Single Sign-on erzwingen",
  "Password sign-in stops for everyone except administrators, who keep it as a way in if the provider is down.": "Die Passwortanmeldung endet für alle außer Administratoren, die sie als Zugang behalten, falls der Anbieter ausfällt.",
  "Save sign-in settings": "Anmeldeeinstellungen speichern",
  "Testing…": "Wird getestet …",
  "Test sign-in": "Anmeldung testen",
  "Turn off single sign-on": "Single Sign-on ausschalten",
  "Save is waiting for the fields marked above.": "Speichern wartet auf die oben markierten Felder.",
  "Password sign-in": "Passwortanmeldung",
  "These rules are fixed and apply to every password account. They are not settings.": "Diese Regeln sind fest und gelten für jedes Passwortkonto. Sie sind keine Einstellungen.",
  "Password rules": "Passwortregeln",
  "At least 12 characters, not the email name, and not a common password": "Mindestens 12 Zeichen, nicht der E-Mail-Name und kein gängiges Passwort",
  "Lockout": "Sperre",
  "10 failed sign-ins lock the account for 15 minutes": "10 fehlgeschlagene Anmeldungen sperren das Konto für 15 Minuten",
  "Password sign-in will stop for everyone except administrators. People who cannot sign in through the identity provider will be locked out until an administrator changes this.": "Die Passwortanmeldung endet für alle außer Administratoren. Wer sich nicht über den Identitätsanbieter anmelden kann, ist ausgesperrt, bis ein Administrator dies ändert.",
  "Keep password sign-in": "Passwortanmeldung behalten",
  "The settings are removed. People who signed in through the identity provider keep their accounts and sign in with a password; those who never set one use Forgot password.": "Die Einstellungen werden entfernt. Wer sich über den Identitätsanbieter angemeldet hat, behält sein Konto und meldet sich mit einem Passwort an; wer nie eines festgelegt hat, nutzt „Passwort vergessen“.",
  "Keep single sign-on": "Single Sign-on behalten",
  "Sign-in page": "Anmeldeseite",
  "Changing sign-in": "Anmeldung ändern",
  "Connect Meridian to your identity provider with OpenID Connect.": "Verbinden Sie Meridian mit OpenID Connect mit Ihrem Identitätsanbieter.",
  "What people see when they sign in, and who may use single sign-on.": "Was Personen bei der Anmeldung sehen und wer Single Sign-on verwenden darf.",
  "The sign-in settings": "Die Anmeldeeinstellungen",
