  "Version {latest_version} is available, but automatic updates are not set up on this deployment. Run the update script, or contact support.": "Version {latest_version} ist verfügbar, aber automatische Aktualisierungen sind auf dieser Installation nicht eingerichtet. Führen Sie das Aktualisierungsskript aus oder wenden Sie sich an den Support.",
  "Updates": "Aktualisierungen",
  "Running an update needs the manage system permission.": "Zum Ausführen einer Aktualisierung ist die Berechtigung „System verwalten“ nötig.",
  "Update {state}{value}.": "Aktualisierung {state}{value}.",
