  "Nothing is waiting because no run has scored an object yet. Run an analysis and the rows that fail land here, ranked by value at risk.": "Nichts wartet, weil noch kein Lauf ein Objekt bewertet hat. Führen Sie eine Analyse aus, und die fehlerhaften Zeilen landen hier, nach gefährdetem Wert geordnet.",
