  "No SAP system is connected yet. Connect one, extract it and run an analysis, and every object appears here with its score.": "Es ist noch kein SAP-System verbunden. Verbinden Sie eines, extrahieren Sie es und führen Sie eine Analyse aus, und jedes Objekt erscheint hier mit seinem Score.",
