  "Edit the rules": "Regeln bearbeiten",
  "No survivorship rule is set for this object, so a merge keeps the survivor's value for every field. Add one with Edit the rules.": "Für dieses Objekt ist keine Überlebensregel festgelegt, daher behält ein Zusammenführen für jedes Feld den Wert des überlebenden Datensatzes. Legen Sie eine mit Regeln bearbeiten an.",
