  "{blocked} of {stepsCount} {stepsCount, plural, one {step} other {steps}} blocked": "{blocked} von {stepsCount} {stepsCount, plural, one {Schritt} other {Schritten}} blockiert",
  "Edit the process model, its steps and the fields each step reads in the process designer. Changes there show here on the next run.": "Bearbeiten Sie das Prozessmodell, seine Schritte und die Felder, die jeder Schritt liest, im Prozessdesigner. Änderungen dort erscheinen hier beim nächsten Lauf.",
  "The process readiness of {label} could not be read.": "Die Prozessbereitschaft von {label} konnte nicht gelesen werden.",
  "No process step reads the fields of {label}. Process readiness fills for objects that a step of the process model reads, such as Material master in Procure to Pay; add the object to a step in the designer.": "Kein Prozessschritt liest die Felder von {label}. Die Prozessbereitschaft füllt sich für Objekte, die ein Schritt des Prozessmodells liest, etwa Materialstamm in Procure to Pay; fügen Sie das Objekt im Designer einem Schritt hinzu.",
  "No process step is blocked by {label}. Every step that reads its fields is ready in this run.": "Kein Prozessschritt wird durch {label} blockiert. Jeder Schritt, der seine Felder liest, ist in diesem Lauf bereit.",
  "{blockedCount} of {stepsCount} process {stepsCount, plural, one {step is} other {steps are}} blocked by {label}: {map}{value}.": "{blockedCount} von {stepsCount} {stepsCount, plural, one {Prozessschritt ist} other {Prozessschritten sind}} durch {label} blockiert: {map}{value}.",
  "{l1Id} step {number}": "{l1Id} Schritt {number}",
