  "{accepted} suggested values for {id} are in your draft batch {draft_batch_id}. Nothing reaches SAP until an owner approves.": "{accepted} vorgeschlagene Werte für {id} sind in Ihrem Entwurfsstapel {draft_batch_id}. Nichts erreicht SAP, bevor ein Eigentümer freigibt.",
