  "A rule that blocks or degrades several features is counted under each. Features come from the impact model for this run.": "Eine Regel, die mehrere Funktionen blockiert oder beeinträchtigt, wird unter jeder gezählt. Funktionen stammen aus dem Auswirkungsmodell dieses Laufs.",
  "Ranked by value at risk{value}. Failing % is of {records_checked} records checked.": "Nach gefährdetem Wert sortiert{value}. Fehler-% bezieht sich auf {records_checked} geprüfte Datensätze.",
