  "This is the earliest run in view, so there is nothing before it to compare. The next run adds the comparison.": "Dies ist der früheste Lauf in der Ansicht, daher gibt es davor nichts zu vergleichen. Der nächste Lauf fügt den Vergleich hinzu.",
