  "Each schedule extracts the object again and re-runs its checks, so trends and alerts see every run. Times are UTC.": "Jeder Zeitplan extrahiert das Objekt erneut und führt seine Prüfungen wieder aus, sodass Trends und Alarme jeden Lauf sehen. Zeiten sind in UTC.",
  "Last": "Letzter",
  "Delete the {domain} schedule": "Zeitplan für {domain} löschen",
