  "Cap rule: {cap_rule}.": "Begrenzungsregel: {cap_rule}.",
  "Retry needs the {permission} permission on this system.": "Für einen erneuten Versuch brauchen Sie die Berechtigung {permission} auf diesem System.",
  "{failing} rules started failing, {fixed} stopped": "{failing} Regeln schlagen neu fehl, {fixed} nicht mehr",
  "{worse} failing rules got worse, {better} got better": "{worse} fehlschlagende Regeln wurden schlechter, {better} besser",
  "Capped at {cap} by {rule}, one critical rule over tolerance.": "Begrenzt auf {cap} durch {rule}, eine kritische Regel über der Toleranz.",
