  "Held at {cap} by {rule}, one critical rule over tolerance. Measured {measured}, shown {score}.": "Gehalten bei {cap} durch {rule}, eine kritische Regel über der Toleranz. Gemessen {measured}, angezeigt {score}.",
  "Held at {cap} by {rule} and {rule2}, two critical rules over tolerance. Measured {measured}, shown {score}.": "Gehalten bei {cap} durch {rule} und {rule2}, zwei kritische Regeln über der Toleranz. Gemessen {measured}, angezeigt {score}.",
  "Held at {cap} by {n} critical rules over tolerance, among them {rule} and {rule2}. Measured {measured}, shown {score}.": "Gehalten bei {cap} durch {n} kritische Regeln über der Toleranz, darunter {rule} und {rule2}. Gemessen {measured}, angezeigt {score}.",
