  "PNG or SVG, {max} KB at most. It replaces the mark in the top bar and on the sign-in page.": "PNG oder SVG, höchstens {max} KB. Es ersetzt das Zeichen in der oberen Leiste und auf der Anmeldeseite.",
  "{max} characters at most, without < or >": "Höchstens {max} Zeichen, ohne < oder >",
  "Links, the selected cell, the current run and the primary button. It must read at 4.5:1 on white.": "Links, die ausgewählte Zelle, der aktuelle Lauf und die Hauptschaltfläche. Er muss auf Weiß mit 4,5:1 lesbar sein.",
