  "Part of the storage is not encrypted at rest. Turn it on in the database and storage configuration of this deployment.": "Ein Teil des Speichers ist nicht ruhend verschlüsselt. Schalten Sie es in der Datenbank- und Speicherkonfiguration dieser Bereitstellung ein.",
