  "Changes only since last full download": "Nur Änderungen seit dem letzten vollständigen Download",
  "Re-reads only the records whose SAP change date is after the last full download of the same objects and scope; tables without change dates are read in full. With no earlier download, everything is read.": "Liest nur die Datensätze neu, deren SAP-Änderungsdatum nach dem letzten vollständigen Download derselben Objekte und desselben Umfangs liegt; Tabellen ohne Änderungsdatum werden vollständig gelesen. Gibt es keinen früheren Download, wird alles gelesen.",
  "Extraction of changes started": "Extraktion der Änderungen gestartet",
  ", changes only since the last full download": ", nur Änderungen seit dem letzten vollständigen Download",
  "Events": "Ereignisse",
  "Config drift alerts": "Konfigurationsdrift-Warnungen",
  "After a configuration load or sync, tell the owners of the objects whose rules read a changed table, and re-score them.": "Nach einem Konfigurationsladen oder -abgleich die Verantwortlichen der Objekte informieren, deren Regeln eine geänderte Tabelle lesen, und sie neu bewerten.",
  "Repeated fixes that make a learned rule": "Wiederholte Korrekturen, die eine gelernte Regel ergeben",
  "The same fix in this many records proposes a rule. From 2.": "Dieselbe Korrektur in so vielen Datensätzen schlägt eine Regel vor. Ab 2.",
  "A whole number from 2 to 100,000.": "Eine ganze Zahl von 2 bis 100.000.",
  "Alert when a score drops by points": "Warnen, wenn ein Score um so viele Punkte fällt",
