  "No certificate has been issued for {name}. Issue one when every object is measured and no critical rule is over tolerance.": "Für {name} wurde noch kein Zertifikat ausgestellt. Stellen Sie eines aus, sobald jedes Objekt gemessen ist und keine kritische Regel über der Toleranz liegt.",
