  "This wave does not exist. It may have been deleted.": "Diese Welle existiert nicht. Sie wurde möglicherweise gelöscht.",
  "this wave": "diese Welle",
  "A certificate fixes the score of each object of the wave at its latest run, with the exceptions and contracts behind it, and a SHA-256 of that content. A new version replaces nothing: every version stays.": "Ein Zertifikat hält den Score jedes Objekts der Welle bei seinem letzten Lauf fest, mit den Ausnahmen und Verträgen dahinter, und einen SHA-256 dieses Inhalts. Eine neue Version ersetzt nichts: jede Version bleibt erhalten.",
  "Changes by date": "Änderungen nach Datum",
  "Read in full": "Vollständig gelesen",
  "the last download": "dem letzten Download",
