  "Enforced": "Durchgesetzt",
  "Reported only": "Nur gemeldet",
  "Breaches of {name}": "Verstöße gegen {name}",
  "Enforce: while breached, no run of this object can be pinned as the baseline": "Durchsetzen: solange verletzt, kann kein Lauf dieses Objekts als Basis angeheftet werden",
