  "The data contracts of this object could not be read.": "Die Datenverträge dieses Objekts konnten nicht gelesen werden.",
  "No active data contract covers {label}. A contract promises a consumer a minimum score and dimension floors; enforced, it stops a breached run from becoming the baseline.": "Kein aktiver Datenvertrag deckt {label} ab. Ein Vertrag sagt einem Abnehmer einen Mindest-Score und Untergrenzen je Dimension zu; durchgesetzt verhindert er, dass ein verletzender Lauf zur Basis wird.",
  "Changing thresholds and enforcement needs the manage rules permission.": "Schwellenwerte und Durchsetzung zu ändern, erfordert die Berechtigung Regeln verwalten.",
