  "open the run": "Lauf öffnen",
  "Not re-scored: no rule of a scored object reads these tables.": "Nicht neu bewertet: keine Regel eines bewerteten Objekts liest diese Tabellen.",
  "Not re-scored: the run has no stored dataset, or an analysis of it was already running.": "Nicht neu bewertet: der Lauf hat keinen gespeicherten Datensatz, oder eine Analyse läuft bereits.",
