  "Between configuration loads and syncs, newest first": "Zwischen Konfigurationsladen und -abgleichen, neueste zuerst",
  "Drift alerts are turned off for this tenant, so new changes are not compared. An administrator turns them on under Webhooks, Automation.": "Drift-Warnungen sind für diesen Mandanten ausgeschaltet, daher werden neue Änderungen nicht verglichen. Ein Administrator schaltet sie unter Webhooks, Automatisierung ein.",
  "The configuration changes could not be read.": "Die Konfigurationsänderungen konnten nicht gelesen werden.",
  "No configuration change has been seen on this system. When a configuration load or sync changes a table that a rule reads, it shows here with the rules it touches and the owners told.": "Auf diesem System wurde noch keine Konfigurationsänderung gesehen. Wenn ein Konfigurationsladen oder -abgleich eine Tabelle ändert, die eine Regel liest, erscheint sie hier mit den betroffenen Regeln und den informierten Verantwortlichen.",
  "{changes}. {rules} {rules, plural, one {rule depends} other {rules depend}} on it; {owners} {owners, plural, one {owner} other {owners}} told; {rescore}.": "{changes}. {rules} {rules, plural, one {Regel hängt} other {Regeln hängen}} davon ab; {owners} {owners, plural, one {Verantwortlicher} other {Verantwortliche}} informiert; {rescore}.",
