  "{monthly} a month in opportunity cost from {blocked} blocked {blocked, plural, one {feature} other {features}}; {since} since each was first blocked.": "{monthly} Opportunitätskosten im Monat aus {blocked} {blocked, plural, one {blockierter Funktion} other {blockierten Funktionen}}; {since}, seit jede zuerst blockiert wurde.",
