  "Not applied since {when}": "Seit {when} nicht angewendet",
  "Not applied": "Nicht angewendet",
  "Applying or removing a pack needs the manage rules permission.": "Zum Anwenden oder Entfernen eines Pakets brauchen Sie die Berechtigung Regeln verwalten.",
  "{name} applied": "{name} angewendet",
  "{n} {n, plural, one {class} other {classes}} now count as policy breaches when one of their critical rules fails.": "{n} {n, plural, one {Klasse zählt} other {Klassen zählen}} jetzt als Richtlinienverletzung, wenn eine ihrer kritischen Regeln fehlschlägt.",
  "Remove the pack": "Paket entfernen",
  "Apply the pack": "Paket anwenden",
  "Its classes stop counting as policy breaches on the landscape and the receipt. The rules keep running; you can apply the pack again at any time.": "Seine Klassen zählen in der Landschaft und im Beleg nicht mehr als Richtlinienverletzungen. Die Regeln laufen weiter; Sie können das Paket jederzeit wieder anwenden.",
  "Policy packs": "Richtlinienpakete",
  "Reading policy packs": "Richtlinienpakete lesen",
  "{applied} of {n} packs applied. An applied pack's classes count as policy breaches on the landscape and the receipt when one of their critical rules fails. Authorities are cited by article or section.": "{applied} von {n} Paketen angewendet. Die Klassen eines angewendeten Pakets zählen in der Landschaft und im Beleg als Richtlinienverletzung, wenn eine ihrer kritischen Regeln fehlschlägt. Vorschriften werden nach Artikel oder Abschnitt zitiert.",
  "GxP, SOX and GDPR field classes, the authority each answers to, and the rules that evidence them.": "Feldklassen für GxP, SOX und DSGVO, die maßgebliche Vorschrift jeder Klasse und die Regeln, die sie nachweisen.",
  "The policy packs": "Die Richtlinienpakete",
  "No policy pack ships with this version.": "Diese Version enthält kein Richtlinienpaket.",
  "{count} policy {count, plural, one {class} other {classes}} breached: a critical rule evidencing an applied policy pack fails": "{count} {count, plural, one {Richtlinienklasse} other {Richtlinienklassen}} verletzt: eine kritische Regel, die ein angewendetes Richtlinienpaket nachweist, schlägt fehl",
  "Open the classes and evidence": "Klassen und Nachweise öffnen",
  "Digests": "Digests",
  "Managing digests": "Digests verwalten",
  "{cadence}, {zone}": "{cadence}, {zone}",
  "Last sent": "Zuletzt gesendet",
  "{n} {n, plural, one {digest} other {digests}}. Each one sends the landscape sentence, the score moves, the waves and their gates, the approvals waiting, SLA breaches and the top value at risk, by email, to an alert channel or as a webhook event. Numbers only, never SAP values.": "{n} {n, plural, one {Digest} other {Digests}}. Jeder sendet den Landschaftssatz, die Score-Bewegungen, die Wellen mit ihren Gates, die wartenden Genehmigungen, SLA-Verletzungen und den höchsten gefährdeten Wert, per E-Mail, an einen Alarmkanal oder als Webhook-Ereignis. Nur Zahlen, nie SAP-Werte.",
  "Add a digest": "Digest hinzufügen",
  "The digests could not be read. {detail}": "Die Digests konnten nicht gelesen werden. {detail}",
  "No digest yet. Add one for a role, such as the programme lead every Monday, or for a migration wave.": "Noch kein Digest. Fügen Sie einen für eine Rolle hinzu, etwa jeden Montag für die Programmleitung, oder für eine Migrationswelle.",
  "Evidence of": "Nachweis von",
