  "Export load file hands the approved values over as a Migration Cockpit file instead of writing them live. It cannot be taken back.": "„Ladedatei exportieren“ übergibt die freigegebenen Werte als Migration-Cockpit-Datei, statt sie direkt zu schreiben. Das kann nicht zurückgenommen werden.",
