  "Your objects are on the map; the approvals waiting for you are on Work.": "Ihre Objekte stehen auf der Karte; die Freigaben, die auf Sie warten, unter Arbeit.",
  "Your work starts on Work: the records to fix, the ones that hold the most back first.": "Ihre Arbeit beginnt unter Arbeit: die zu korrigierenden Sätze, die mit der größten Wirkung zuerst.",
  "Gate: min score {score}": "Gate: Mindestscore {score}",
  "No readiness score in this wave's run": "Kein Bereitschaftsscore im Lauf dieser Welle",
  "Readiness and records blocked are not shown: no migration run has a readiness score for {label} yet. The verdict comes from its blocking gaps and its score.": "Bereitschaft und blockierte Datensätze werden nicht angezeigt: Noch kein Migrationslauf hat einen Bereitschaftsscore für {label}. Das Urteil ergibt sich aus den blockierenden Lücken und dem Score.",
  "Compare with last month": "Mit dem Vormonat vergleichen",
  "You have unsaved changes. Leave without saving them?": "Sie haben ungespeicherte Änderungen. Ohne Speichern verlassen?",
  "Save and retry the failed job": "Speichern und fehlgeschlagenen Job wiederholen",
  "The workbook leads with the rules you opened here, then the ten rules with the most failing records in this run, with empty SE16 count and match columns for your team.": "Die Arbeitsmappe beginnt mit den Regeln, die Sie hier geöffnet haben, dann folgen die zehn Regeln mit den meisten fehlerhaften Datensätzen dieses Laufs, mit leeren Spalten für SE16-Anzahl und Übereinstimmung für Ihr Team.",
