  "Remind": "Erinnern",
  "Counts are read from the work assigned in the latest state. Open counts the records assigned to the person that are not yet signed off; To approve counts the fix batches that wait for their approval; Overdue counts their open records past the due date; Total counts every open record, assigned or not.": "Die Zahlen stammen aus der zugewiesenen Arbeit im neuesten Stand. Offen zählt die der Person zugewiesenen, noch nicht abgezeichneten Datensätze; Zu genehmigen zählt die Fix-Batches, die auf ihre Genehmigung warten; Überfällig zählt ihre offenen Datensätze nach dem Fälligkeitsdatum; Gesamt zählt jeden offenen Datensatz, zugewiesen oder nicht.",
  "Each count is of records, not issues: one record with three failed rules counts once. Chip counts follow the object, rule and person filters.": "Gezählt werden Datensätze, nicht Probleme: Ein Datensatz mit drei verletzten Regeln zählt einmal. Die Zahlen der Chips folgen den Filtern für Objekt, Regel und Person.",
